// IsNewProducerContract reports whether name is allowed for newly emitted payloads.
func IsNewProducerContract(name string) bool {
	lifecycle, ok := ContractLifecycleByName[name]
	return ok && lifecycle.NewProducer == "allowed"
}

// RequireNewProducerContract rejects deprecated, migration-only and unknown contracts.
func RequireNewProducerContract(name string) error {
	if IsNewProducerContract(name) {
		return nil
	}
	lifecycle, ok := ContractLifecycleByName[name]
	if !ok {
		return ContractValidationError(name + ": unknown contract; new producer forbidden")
	}
	replacement := "<none>"
	if lifecycle.Replacement != nil {
		replacement = *lifecycle.Replacement
	}
	return ContractValidationError(name + ": forbidden for new producers; replacement=" + replacement)
}

