// ManifestRole BindingManifest 内的角色条目（services/identity ManifestRole.to_dict）。
type ManifestRole struct {
	// person_id string
	PersonID string `json:"person_id"`
	// role BindingRole
	Role BindingRole `json:"role"`
	// permissions []string
	Permissions []string `json:"permissions"`
}

// Validate 执行 fail-closed 结构校验（pattern/format 由消费方解析时校验）。
func (m *ManifestRole) Validate() error {
	if len([]rune(m.PersonID)) < 1 {
		return ContractValidationError("ManifestRole.person_id: too short")
	}
	if len([]rune(m.PersonID)) > 128 {
		return ContractValidationError("ManifestRole.person_id: too long")
	}
	if !IsValidBindingRole(m.Role) {
		return ContractValidationError("ManifestRole.role: unknown canonical value")
	}
	if len(m.Permissions) > 64 {
		return ContractValidationError("ManifestRole.permissions: too many items")
	}
	{
		seen0 := make(map[string]struct{}, len(m.Permissions))
		for _, uniqueItem0 := range m.Permissions {
			uniqueKey0 := stableJSONKey(uniqueItem0)
			if _, duplicate := seen0[uniqueKey0]; duplicate {
				return ContractValidationError("ManifestRole.permissions: duplicate items")
			}
			seen0[uniqueKey0] = struct{}{}
		}
	}
	for _, item0 := range m.Permissions {
		if len([]rune(item0)) < 1 {
			return ContractValidationError("ManifestRole.permissions[]: too short")
		}
		if len([]rune(item0)) > 64 {
			return ContractValidationError("ManifestRole.permissions[]: too long")
		}
	}
	return nil
}

